/* TimeWorth UI preview. All records are fictional and stay in this browser. */
const icons={home:'<path d="m3 10 9-7 9 7v9a2 2 0 0 1-2 2h-4v-7H9v7H5a2 2 0 0 1-2-2z"/>',book:'<path d="M5 3h13a1 1 0 0 1 1 1v17H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3Z"/><path d="M3 17a3 3 0 0 1 3-3h13M8 7h6"/>',plan:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a7 7 0 0 1 7-7h2a7 7 0 0 1 7 7v2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 12h4"/>',plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',calc:'<rect x="5" y="2" width="14" height="20" rx="3"/><path d="M8 6h8M8 11h1m6 0h1m-8 4h1m6 0h1m-8 4h1m6-4v4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',up:'<path d="m5 16 5-5 4 4 5-9m-5 0h5v5"/>',coffee:'<path d="M4 8h12v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4zm12 1h2a3 3 0 1 1 0 6h-2M7 2v2m4-2v2"/>',food:'<path d="M4 3v7a2 2 0 0 0 4 0V3M6 3v18m12 0V3c-4 0-5 10 0 10"/>',bag:'<path d="M4 7h16l-1 14H5L4 7Zm4 0V6a4 4 0 0 1 8 0v1"/>',house:'<path d="m3 11 9-8 9 8M5 9v12h14V9m-9 12v-7h4v7"/>',mountain:'<path d="m2 20 7-14 6 14M9 13l-3-1m8 0 3-6 5 14M1 20h22"/><circle cx="13" cy="4" r="1"/>',headphone:'<path d="M4 16v-4a8 8 0 0 1 16 0v4"/><rect x="2" y="12" width="5" height="9" rx="2"/><rect x="17" y="12" width="5" height="9" rx="2"/>',plane:'<path d="m22 2-7 20-4-9-9-4 20-7ZM11 13l11-11"/>',wallet:'<path d="M20 7V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v12H5a3 3 0 0 1-3-3V6"/><path d="M20 11h-5v6h5m-4-3h1"/>',moon:'<path d="M20.5 14.5A9 9 0 0 1 9.5 3.5a9 9 0 1 0 11 11Z"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10s-8-5-8-10V6l8-4Z"/><path d="m8 12 3 3 5-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',edit:'<path d="m15 4 5 5M4 20l4-1L21 6a2 2 0 0 0-4-4L4 15l-1 6 5-2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',x:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4L19 6"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>',reset:'<path d="M3 10a9 9 0 1 1 2 9M3 3v7h7"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.bag}</svg>`;
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>({salary:10000,days:22,hours:8,commute:2,workCost:600,dark:false,additionalSpend:0,monthlySaving:2000,saved:3200,transactions:[{id:'coffee-21',name:'街角咖啡',category:'日常',amount:24,date:'今天',time:'09:26',account:'支付宝',icon:'coffee'},{id:'lunch-21',name:'午间的一顿好饭',category:'日常',amount:38,date:'今天',time:'12:18',account:'微信',icon:'food'},{id:'grocery-20',name:'一周的日常采购',category:'日常',amount:286,date:'昨天',time:'18:42',account:'支付宝',icon:'bag'},{id:'shoes-18',name:'一双舒服的运动鞋',category:'购物',amount:432,date:'10月18日',time:'20:15',account:'银行卡',icon:'bag'},{id:'rent-01',name:'这个月的房租',category:'居住',amount:2500,date:'10月1日',time:'08:00',account:'银行卡',icon:'house'}],wishes:[{name:'降噪耳机',price:1999,icon:'headphone'},{name:'一场轻装旅行',price:4800,icon:'plane'},{name:'给自己的学习计划',price:1200,icon:'book'}]});
let state=defaults();try{const saved=JSON.parse(localStorage.getItem('timeworth-ui-v1'));if(saved&&Number.isFinite(saved.salary)&&Array.isArray(saved.transactions)&&Array.isArray(saved.wishes)&&saved.salary>0&&saved.days>0&&saved.hours>0)state={...state,...saved};}catch{}
let page='home',filter='全部',planTab='repay',selectedMonth=0,rateMode='work',calcTerms=1,lastFocus=null,toastTimer;
const navItems=[['home','首页','home'],['ledger','账本','book'],['plan','计划','plan'],['profile','我的','user']];
const repay=[1260,1260,990,720,0,0],months=['10月','11月','12月','1月','2月','3月'];
const app=document.querySelector('#app-content'),sheet=document.querySelector('#sheet'),backdrop=document.querySelector('#sheet-backdrop');
const save=()=>{try{localStorage.setItem('timeworth-ui-v1',JSON.stringify(state));}catch{}};
const money=(value,decimals=0)=>new Intl.NumberFormat('zh-CN',{minimumFractionDigits:decimals,maximumFractionDigits:decimals}).format(value);
const rate=()=>state.salary/(state.days*state.hours);
const realRate=()=>Math.max(0,state.salary-state.workCost)/(state.days*(state.hours+state.commute));
const spending=()=>state.transactions.reduce((sum,t)=>sum+t.amount,0);
const available=()=>state.salary-7540-state.additionalSpend;
const duration=value=>{const minutes=Math.round(Math.max(0,value)/rate()*60);const h=Math.floor(minutes/60),m=minutes%60;return h?`${h}小时${m?m+'分钟':''}`:`${m}分钟`;};
const txClass=t=>t.category==='日常'?'food':t.category==='居住'?'home':'shopping';
function toast(message){const element=document.querySelector('#toast');element.textContent=message;element.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>element.classList.remove('visible'),2400);}
function header(title,actions=''){return `<div class="topline"><span class="date-caption">10月21日 · 星期三</span><span class="demo-badge">演示数据</span></div><div class="page-heading"><h2>${title}</h2><div class="header-actions">${actions}</div></div>`;}
function transaction(t){return `<button class="transaction" data-action="transaction" data-id="${escapeHTML(t.id)}"><span class="tx-icon ${txClass(t)}">${icon(t.icon)}</span><span class="tx-copy"><span class="tx-name">${escapeHTML(t.name)}</span><span class="tx-meta" style="display:block">${escapeHTML(t.account)} · ${escapeHTML(t.time)}</span></span><span class="tx-right"><span class="tx-amount">−¥${money(t.amount,t.amount%1?2:0)}</span><span class="tx-time" style="display:block">≈ ${duration(t.amount)}</span></span></button>`;}
function section(title,action,label='查看全部'){return `<div class="section-heading"><h3>${title}</h3>${action?`<button class="text-link" data-action="${action}">${label}${icon('chevron')}</button>`:''}</div>`;}
function goal(){const percent=Math.min(100,Math.round(state.saved/8000*100)),left=Math.max(0,Math.ceil((8000-state.saved)/state.monthlySaving));return `<button class="card goal-card" data-action="goal"><div class="goal-top"><span class="goal-icon">${icon('mountain')}</span><span><span class="goal-name">去看一次山海</span><span class="goal-sub" style="display:block">给生活留一点期待</span></span><span class="goal-percentage">${percent}<small>%</small></span></div><div class="progress"><span style="width:${percent}%"></span></div><div class="goal-bottom"><span>已存 ¥${money(state.saved)} / ¥8,000</span><span>${left?`预计 ${left} 个月后出发`:'已经准备好了'}</span></div></button>`;}
function home(){return header('我的生活',`<button class="icon-button bell-button" data-action="notifications" aria-label="查看提醒">${icon('bell')}</button><button class="avatar" data-page="profile" aria-label="查看我的工作">时</button>`)+`<section class="card cash-card"><div class="cash-top"><span class="cash-label">本月可自由安排 ${icon('info')}</span><button class="month-chip" data-action="budget">10月${icon('down')}</button></div><div class="cash-number"><span class="currency">¥</span>${money(available())}</div><div class="cash-foot"><span class="up-badge">${icon('up')} 比上月多 ¥380</span><span>已预留计划开销与应还</span></div><div class="cash-track" aria-label="必要开销42%，应还12.6%，其他预算20.8%，可安排24.6%"><span class="track-essential"></span><span class="track-repay"></span><span class="track-other"></span><span class="track-free"></span></div><div class="cash-legend"><span><i class="legend-dot"></i>必要开销</span><span><i class="legend-dot repay"></i>分期应还</span><span><i class="legend-dot other"></i>其他预算</span><span><i class="legend-dot free"></i>可安排</span></div></section><div class="quick-actions"><button class="quick-button primary" data-action="calculator">${icon('calc')}算一笔消费</button><button class="quick-button secondary" data-action="import">${icon('upload')}导入账单</button></div>${section('时间与收入','rate','计算口径')}<button class="card time-card" data-action="rate"><div class="time-top">${icon('clock')} 你的到手时薪</div><div class="time-price">¥${money(rate(),2)}<small>/ 小时</small></div><div class="time-subtitle">每月 ${state.days*state.hours} 小时 · 不含通勤</div><div class="time-orbit"></div>${icon('clock','orbit-clock')}</button><div class="metric-grid"><button class="card metric-card" data-page="ledger"><div class="metric-label">${icon('wallet')}本月消费</div><div class="metric-value">¥${money(spending(),spending()%1?2:0)}</div><div class="metric-hint">约 ${duration(spending())}工作收入</div></button><button class="card metric-card" data-page="plan"><div class="metric-label">${icon('plan')}本月应还</div><div class="metric-value">¥1,260</div><div class="metric-hint"><span class="small-dot"></span>最近一笔 · 10月25日</div></button></div>${section('最近的日常','go-ledger')}<div class="card transaction-list">${state.transactions.slice(0,2).map(transaction).join('')}</div>${section('正在靠近的心愿','go-wishes','我的心愿')}${goal()}<p class="subtle-note">以自己的节奏，让生活慢慢变好。</p>`;}
function ledger(){const records=state.transactions.filter(t=>filter==='全部'||t.category===filter),groups=[...new Set(records.map(t=>t.date))];return header('账本',`<button class="icon-button" data-action="import" aria-label="导入账单">${icon('upload')}</button><button class="icon-button" data-action="add" aria-label="添加消费">${icon('plus')}</button>`)+`<div class="card summary-card"><div class="summary-top"><span>10月 · 支出</span><button class="text-link" data-action="accounts">全部账户${icon('down')}</button></div><div class="summary-number"><small>¥</small>${money(spending(),spending()%1?2:0)}</div><div class="summary-bottom">${icon('clock')}相当于 ${duration(spending())}工作收入</div><div class="mini-bars" aria-label="演示每日消费趋势">${[18,33,24,47,21,39,18,30,70,43,25,34,20,55,37,78,26,46,30,39,52].map((h,i)=>`<span class="${i===20?'current':''}" style="height:${h}%"></span>`).join('')}</div><div class="chart-labels"><span>10月1日</span><span>10月11日</span><span>今天</span></div></div><div class="filters" role="group" aria-label="消费分类">${['全部','日常','购物','居住'].map(name=>`<button class="filter-chip ${filter===name?'active':''}" data-filter="${name}" aria-pressed="${filter===name}">${name}</button>`).join('')}</div>${groups.length?groups.map(date=>`<div class="group-date"><span>${date}</span><span>¥${money(records.filter(t=>t.date===date).reduce((s,t)=>s+t.amount,0),2)}</span></div><div class="card transaction-list ledger-list">${records.filter(t=>t.date===date).map(transaction).join('')}</div>`).join(''):'<div class="empty-state">这里还没有记录，先记一笔吧。</div>'}<p class="subtle-note">每一笔日常，都有自己的意义。</p>`;}
function plan(){return header('生活计划',`<button class="icon-button" data-action="${planTab==='repay'?'notifications':'calculator'}" aria-label="${planTab==='repay'?'查看还款提醒':'添加心愿'}">${icon(planTab==='repay'?'bell':'plus')}</button>`)+`<div class="segmented" role="group" aria-label="计划类型"><button class="${planTab==='repay'?'active':''}" data-plan="repay">还款安排</button><button class="${planTab==='wishes'?'active':''}" data-plan="wishes">心愿与目标</button></div>`+(planTab==='repay'?`<div class="card summary-card"><div class="summary-top"><span>本月待还</span><span class="demo-badge">2 笔安排</span></div><div class="summary-number"><small>¥</small>1,260</div><div class="summary-bottom">${icon('clock')}约 ${duration(1260)}工作收入</div></div><button class="card debt-card" data-debt="huabei"><div class="debt-top"><span class="debt-logo">花</span><span><span class="debt-title">花呗</span><span class="debt-caption" style="display:block">10月账单 · 25日到期</span></span><span class="debt-amount">¥720</span></div><div class="debt-bottom"><span>剩余 4 期 · 合计 ¥2,880</span>${icon('chevron')}</div></button><button class="card debt-card" data-debt="baitiao"><div class="debt-top"><span class="debt-logo jd">白</span><span><span class="debt-title">京东白条</span><span class="debt-caption" style="display:block">10月账单 · 28日到期</span></span><span class="debt-amount">¥540</span></div><div class="debt-bottom"><span>剩余 3 期 · 合计 ¥1,350</span>${icon('chevron')}</div></button>${section('未来几个月')}<div class="card chart-card"><div class="chart-top"><span>${selectedMonth<3?'2026年':'2027年'}${months[selectedMonth]}应还</span><strong>¥${money(repay[selectedMonth])}</strong></div><div class="repay-chart" role="group" aria-label="选择月份查看应还">${repay.map((n,i)=>`<button class="repay-bar-group ${i===selectedMonth?'active':''}" data-month="${i}" aria-label="${months[i]}应还${n}元"><span class="repay-bar" style="height:${Math.max(4,n/1260*80)}px"></span><span>${months[i]}</span></button>`).join('')}</div></div><div class="insight">${icon('spark')}<span>按当前计划，<strong>明年2月起</strong><br>每月可以多安排 ¥1,260。</span></div><p class="subtle-note">按演示分期估算 · 实际金额以平台账单为准</p>`:`${goal()}${section('想买的，也慢慢来','calculator','添加心愿')}<div class="wishlist">${state.wishes.map((w,i)=>`<button class="card wish-card" data-wish="${i}"><span class="wish-icon ${w.icon==='plane'?'travel':w.icon==='book'?'book':''}">${icon(w.icon)}</span><span class="wish-copy"><span class="wish-name">${escapeHTML(w.name)}</span><span class="wish-sub" style="display:block">≈ ${duration(w.price)}工作收入</span></span><span class="wish-price">¥${money(w.price)}</span></button>`).join('')}</div><div class="insight">${icon('spark')}<span>喜欢的东西，可以先放在这里。<br>给自己一点时间，再做决定。</span></div>`);}
function profile(){return header('我的')+`<div class="profile-header"><span class="profile-avatar">时</span><span><span class="profile-title">把生活过成自己的</span><span class="profile-sub" style="display:block">TimeWorth · 个人空间</span></span></div><div class="card work-card"><div class="work-card-title"><span>我的工作</span><button data-action="work">编辑${icon('edit')}</button></div><div class="work-salary">¥${money(state.salary)}<small>/ 月 · 到手收入</small></div><div class="work-stat-row"><div class="work-stat">${state.days}<small> 天</small><span>每月工作</span></div><div class="work-stat">${state.hours}<small> 小时</small><span>每天工作</span></div><div class="work-stat">¥${money(rate(),2)}<span>到手时薪</span></div></div></div><div class="card settings-group"><button class="setting-row" data-action="rate">${icon('clock')}<span class="setting-row-label">时薪计算口径</span><span class="setting-row-value">查看明细${icon('chevron')}</span></button><button class="setting-row" data-action="accounts">${icon('wallet')}<span class="setting-row-label">账户与账单</span><span class="setting-row-value">3 个演示账户${icon('chevron')}</span></button><button class="setting-row" data-action="theme">${icon('moon')}<span class="setting-row-label">深色外观</span><span class="toggle ${state.dark?'on':''}" role="switch" aria-checked="${state.dark}" aria-label="深色外观"></span></button></div><div class="card settings-group"><button class="setting-row" data-action="privacy">${icon('shield')}<span class="setting-row-label">数据与隐私</span><span class="setting-row-value">本机演示${icon('chevron')}</span></button><button class="setting-row" data-action="about">${icon('info')}<span class="setting-row-label">关于此预览</span><span class="setting-row-value">设计 01${icon('chevron')}</span></button><button class="setting-row" data-action="reset">${icon('reset')}<span class="setting-row-label">重置演示数据</span><span class="setting-row-value">${icon('chevron')}</span></button></div><div class="profile-footer"><span class="footer-brand">TimeWorth</span><span>你的时间，你的生活。</span><span>UI PREVIEW · ALL DATA IS FICTIONAL</span></div>`;}
function render(){document.querySelector('#app-shell').classList.toggle('dark',state.dark);app.innerHTML=`<div class="page-enter">${({home,ledger,plan,profile}[page])()}</div>`;document.querySelector('#tab-bar').innerHTML=navItems.map(([key,label,name])=>`<button class="tab ${page===key?'active':''}" data-page="${key}" ${page===key?'aria-current="page"':''}>${icon(name)}<span>${label}</span></button>`).join('');document.querySelector('#desktop-nav').innerHTML=navItems.map(([key,label])=>`<button class="desktop-tab ${page===key?'active':''}" data-page="${key}">${label}</button>`).join('');}
function navigate(next){closeSheet(false);page=next;render();app.scrollTop=0;}
function openSheet(title,description,body){lastFocus=document.activeElement;sheet.innerHTML=`<div class="sheet-handle"></div><div class="sheet-heading"><h2>${title}</h2><button class="sheet-close" data-action="close-sheet" aria-label="关闭">${icon('x')}</button></div>${description?`<p class="sheet-description">${description}</p>`:''}${body}`;sheet.setAttribute('aria-label',title);sheet.hidden=false;backdrop.hidden=false;app.inert=true;document.querySelector('#tab-bar').inert=true;sheet.focus({preventScroll:true});}
function closeSheet(restore=true){sheet.hidden=true;backdrop.hidden=true;app.inert=false;document.querySelector('#tab-bar').inert=false;if(restore&&lastFocus?.isConnected)lastFocus.focus({preventScroll:true});}
function calculator(price=2999,name='降噪耳机'){calcTerms=1;openSheet('算一笔消费','把价格换成时间，也看看它会怎样影响这个月。',`<div class="field"><label for="wish-name">想买什么</label><input id="wish-name" maxlength="40" value="${escapeHTML(name)}" placeholder="给这份心愿起个名字"></div><div class="amount-field"><div class="amount-label">商品价格</div><div class="amount-input"><span>¥</span><input id="calc-price" type="number" inputmode="decimal" min="0" max="9999999" step="0.01" value="${price}" aria-label="商品价格"></div></div><div class="sheet-options" role="group" aria-label="付款方式">${[[1,'一次付清'],[3,'分 3 期'],[12,'分 12 期']].map(([n,label])=>`<button class="option-chip ${n===1?'active':''}" data-terms="${n}">${label}</button>`).join('')}</div><div id="calc-output"></div><button class="sheet-button" data-action="save-wish">先加入心愿清单</button><p class="sheet-small-note">演示按免息分期估算，实际费用以平台为准。</p>`);updateCalculator();}
function updateCalculator(){const raw=Number(document.querySelector('#calc-price').value),price=Number.isFinite(raw)?Math.min(9999999,Math.max(0,raw)):0,total=Math.round(price/rate()*60),hours=Math.floor(total/60),minutes=total%60,balance=available()-price/calcTerms;document.querySelector('#calc-output').innerHTML=`<div class="calc-result"><div class="calc-label">相当于你的工作收入</div><div class="calc-time">${hours}<small>小时</small>${minutes}<small>分钟</small></div><div class="calc-detail">按到手时薪 ¥${money(rate(),2)} 计算</div></div><div class="detail-list"><div class="detail-row"><span>${calcTerms===1?'这次需支付':'每期需支付'}</span><strong>¥${money(price/calcTerms,2)}</strong></div><div class="detail-row"><span>本月可安排金额将剩余</span><strong class="${balance<0?'warning':''}">${balance<0?'−':''}¥${money(Math.abs(balance),2)}</strong></div></div>`;}
function rateSheet(){rateMode='work';openSheet('一小时的价值','两种口径，帮你更完整地理解工作的投入与收入。',`<div class="segmented rate-switch"><button class="active" data-rate="work">工作时间</button><button data-rate="real">含通勤与成本</button></div><div id="rate-output"></div><button class="sheet-button light" data-action="work">编辑我的工作信息</button>`);updateRate();}
function updateRate(){const detailed=rateMode==='real',value=detailed?realRate():rate();document.querySelector('#rate-output').innerHTML=`<div class="card rate-detail-card"><div class="calc-label">${detailed?'考虑工作额外投入后的时薪':'你的到手时薪'}</div><div class="time-price">¥${money(value,2)}<small>/ 小时</small></div><div class="formula">${detailed?`（¥${money(state.salary)} − ¥${money(state.workCost)}）<br>÷（${state.days*state.hours} 小时工作 + ${state.days*state.commute} 小时通勤）`:`¥${money(state.salary)} 到手收入<br>÷ ${state.days} 天 ÷ ${state.hours} 小时`}</div></div><div class="detail-list"><div class="detail-row"><span>月到手收入</span><strong>¥${money(state.salary)}</strong></div><div class="detail-row"><span>每月工作时间</span><strong>${state.days*state.hours} 小时</strong></div>${detailed?`<div class="detail-row"><span>每月通勤时间</span><strong>${state.days*state.commute} 小时</strong></div><div class="detail-row"><span>因工作额外产生的支出</span><strong>¥${money(state.workCost)}</strong></div>`:''}</div><p class="sheet-small-note">消费换算目前采用“工作时间”口径。</p>`;}
function workSheet(){openSheet('我的工作','先填基础信息，就能看到自己的时间价值。此处修改仅影响演示。',`<form id="work-form"><div class="field"><label for="salary">每月到手收入（元）</label><input id="salary" name="salary" type="number" min="1" max="9999999" step="0.01" required value="${state.salary}"></div><div class="field-grid"><div class="field"><label for="days">每月工作天数</label><input id="days" name="days" type="number" min="1" max="31" step="1" required value="${state.days}"></div><div class="field"><label for="hours">每天工作小时</label><input id="hours" name="hours" type="number" min="0.5" max="24" step="0.5" required value="${state.hours}"></div></div><div class="field-grid"><div class="field"><label for="commute">每天往返通勤（小时）</label><input id="commute" name="commute" type="number" min="0" max="12" step="0.5" required value="${state.commute}"></div><div class="field"><label for="workCost">每月额外工作成本（元）</label><input id="workCost" name="workCost" type="number" min="0" max="999999" step="1" required value="${state.workCost}"></div></div><button class="sheet-button" type="submit">保存工作信息</button></form>`);}
function importSheet(){openSheet('导入账单','先体验账单核对流程。这里使用演示记录，不连接真实账户，也不上传文件。',`<div class="import-sources">${[['支付宝','支',''],['微信','微','wx'],['花呗','花','hb'],['京东白条','白','jd']].map(([name,logo,cls])=>`<button class="import-source" data-source="${name}"><span class="source-logo ${cls}">${logo}</span>${name}</button>`).join('')}</div><div class="import-upload">${icon('upload')}选择一个来源<br><span style="font-size:9px;color:var(--muted)">查看预览、重复提示和待核对记录</span></div>`);}
function importPreview(source){const already=state.transactions.some(t=>t.id==='demo-import');openSheet('核对导入记录',`${escapeHTML(source)} · 演示账单 · 3 笔记录`, `<div class="card transaction-list"><label class="import-record"><input type="checkbox" id="import-new" ${already?'disabled':'checked'}><span class="tx-copy"><span class="tx-name">便利店的日常补给</span><span class="record-status ${already?'duplicate':''}" style="display:table">${already?'已导入':'新增记录'}</span></span><span class="tx-amount">¥20.90</span></label><label class="import-record"><input type="checkbox" disabled><span class="tx-copy"><span class="tx-name">街角咖啡</span><span class="record-status duplicate" style="display:table">疑似重复 · 默认跳过</span></span><span class="tx-amount">¥24.00</span></label><label class="import-record"><input type="checkbox" disabled><span class="tx-copy"><span class="tx-name">订单退款</span><span class="record-status review" style="display:table">待核对原消费 · 本次不导入</span></span><span class="tx-amount">¥79.00</span></label></div><div class="insight">${icon('shield')}<span>消费与还款分别处理，重复记录先核对。<br>正式导入会依据实际账单格式适配。</span></div><button class="sheet-button" data-action="confirm-import" data-source="${escapeHTML(source)}">确认演示导入</button>`);}
function addSheet(){openSheet('记一笔日常','随手记下，让每一笔支出都有迹可循。',`<form id="expense-form"><div class="field"><label for="expense-name">消费名称</label><input id="expense-name" name="name" maxlength="40" placeholder="例如，一顿晚饭" required></div><div class="field"><label for="expense-amount">消费金额（元）</label><input id="expense-amount" name="amount" type="number" inputmode="decimal" min="0.01" max="999999" step="0.01" placeholder="0.00" required></div><button class="sheet-button" type="submit">保存这笔消费</button></form>`);}
function goalSheet(){const left=Math.max(0,Math.ceil((8000-state.saved)/state.monthlySaving));openSheet('去看一次山海','想去的地方，正在一步步靠近。',`${goal()}<div class="detail-list"><div class="detail-row"><span>目标金额</span><strong>¥8,000</strong></div><div class="detail-row"><span>已为这个目标存下</span><strong>¥${money(state.saved)}</strong></div><div class="detail-row"><span>计划每月存入</span><strong>¥${money(state.monthlySaving)}</strong></div><div class="detail-row"><span>预计还需要</span><strong>${left} 个月</strong></div></div><div class="insight">${icon('mountain')}<span>按稳定存入计划估算。<br>目标里的钱，已经是为期待留好的位置。</span></div><button class="sheet-button" data-action="goal-save">演示存入 ¥200</button><p class="sheet-small-note">只修改演示进度，不发生任何真实转账。</p>`);}
function debtSheet(kind){const hua=kind==='huabei',amount=hua?720:540,schedule=hua?[720,720,720,720]:[540,540,270];openSheet(hua?'花呗 · 还款计划':'京东白条 · 还款计划','演示分期数据，用于预览界面。实际应还以平台账单为准。',`<div class="card summary-card"><div class="summary-top">本月应还</div><div class="summary-number"><small>¥</small>${amount}</div><div class="summary-bottom">${icon('clock')}对应 ${duration(amount)}工作收入</div></div><div class="detail-list">${schedule.map((n,i)=>`<div class="detail-row"><span>${i<3?'2026年':'2027年'}${months[i]}${hua?'25':'28'}日</span><strong>¥${n}</strong></div>`).join('')}<div class="detail-row"><span>剩余合计</span><strong>¥${money(schedule.reduce((a,b)=>a+b,0))}</strong></div></div><p class="sheet-small-note">演示费用为 ¥0 · 不代表实际平台费率</p>`);}
function infoSheet(type){if(type==='budget')openSheet('这个月的安排','按演示预算计算，已发生消费与预留开销不能简单相加。',`<div class="detail-list"><div class="detail-row"><span>到手收入</span><strong>¥${money(state.salary)}</strong></div><div class="detail-row"><span>必要开销预算（含已发生）</span><strong>−¥4,200</strong></div><div class="detail-row"><span>本月分期应还</span><strong>−¥1,260</strong></div><div class="detail-row"><span>其他预留预算</span><strong>−¥2,080</strong></div>${state.additionalSpend?`<div class="detail-row"><span>额外添加的演示消费</span><strong>−¥${money(state.additionalSpend,2)}</strong></div>`:''}<div class="detail-row"><span>本月可自由安排</span><strong>¥${money(available(),2)}</strong></div></div><p class="sheet-small-note">完整现金流将在正式版本中结合账户余额与收付日期计算。</p>`);else if(type==='notifications')openSheet('接下来的提醒','提前安排好，就能多一点从容。',`<div class="alert-item">${icon('plan')}<div><div class="alert-title">10月25日 · 花呗应还 ¥720</div><div class="alert-body">还有 4 天，记得预留还款资金。</div></div></div><div class="alert-item">${icon('plan')}<div><div class="alert-title">10月28日 · 白条应还 ¥540</div><div class="alert-body">还有 7 天，本月应还已计入首页预留。</div></div></div><p class="sheet-small-note">此预览展示固定演示日期，未申请系统通知权限。</p>`);else if(type==='accounts')openSheet('账户与账单','以下是界面演示账户，没有读取任何真实账户。',`<div class="card settings-group">${[['wallet','银行卡','工资与日常收支'],['wallet','支付宝','日常消费'],['wallet','微信','日常消费']].map(([i,n,t])=>`<div class="setting-row">${icon(i)}<span class="setting-row-label">${n}</span><span class="setting-row-value">${t}</span></div>`).join('')}</div><button class="sheet-button" data-action="import">体验账单导入</button>`);else if(type==='privacy')openSheet('数据与隐私','先让数据留在自己手里。',`<div class="alert-item">${icon('shield')}<div><div class="alert-title">只在这个浏览器保存演示修改</div><div class="alert-body">此原型不连接银行、支付宝、花呗或白条，不上传账单。你可以随时重置演示数据。</div></div></div><button class="sheet-button light" data-action="reset">重置演示数据</button>`);else if(type==='about')openSheet('TimeWorth · 设计 01','给安卓手机设计的苹果风格界面。',`<div class="alert-item">${icon('spark')}<div><div class="alert-title">这是可点击的界面预览</div><div class="alert-body">可以切换页面、换算消费、编辑工作信息、体验演示导入和深色外观。数据均为虚构，实际账单接入、APK 和更新功能尚未实现。</div></div></div><p class="sheet-small-note">苹果式的信息层级与留白，兼顾安卓的使用习惯。</p>`);}
document.addEventListener('click',event=>{const target=event.target.closest('button,[data-page]');if(!target)return;if(target.dataset.page){navigate(target.dataset.page);return;}if(target.dataset.filter){filter=target.dataset.filter;render();return;}if(target.dataset.plan){planTab=target.dataset.plan;render();return;}if(target.dataset.month!==undefined){selectedMonth=Number(target.dataset.month);render();return;}if(target.dataset.terms){calcTerms=Number(target.dataset.terms);sheet.querySelectorAll('[data-terms]').forEach(b=>b.classList.toggle('active',Number(b.dataset.terms)===calcTerms));updateCalculator();return;}if(target.dataset.rate){rateMode=target.dataset.rate;sheet.querySelectorAll('[data-rate]').forEach(b=>b.classList.toggle('active',b.dataset.rate===rateMode));updateRate();return;}if(target.dataset.source&&!target.dataset.action){importPreview(target.dataset.source);return;}if(target.dataset.debt){debtSheet(target.dataset.debt);return;}if(target.dataset.wish!==undefined){const w=state.wishes[Number(target.dataset.wish)];calculator(w.price,w.name);return;}const action=target.dataset.action;if(action==='close-sheet')closeSheet();else if(action==='calculator')calculator();else if(action==='rate')rateSheet();else if(action==='work')workSheet();else if(action==='import')importSheet();else if(action==='add')addSheet();else if(action==='goal')goalSheet();else if(action==='go-ledger')navigate('ledger');else if(action==='go-wishes'){planTab='wishes';navigate('plan');}else if(action==='theme'){state.dark=!state.dark;save();render();}else if(action==='save-wish'){const value=Number(document.querySelector('#calc-price').value),name=document.querySelector('#wish-name').value.trim()||'新心愿';if(!Number.isFinite(value)||value<=0){toast('先填一个有效的商品价格');return;}state.wishes.unshift({name:name.slice(0,40),price:Math.min(9999999,value),icon:'bag'});save();planTab='wishes';navigate('plan');toast('心愿已收好，慢慢来');}else if(action==='confirm-import'){const selected=document.querySelector('#import-new').checked&&!document.querySelector('#import-new').disabled;if(selected){state.transactions.unshift({id:'demo-import',name:'便利店的日常补给',amount:20.9,category:'日常',date:'今天',time:'10:36',account:target.dataset.source,icon:'bag'});state.additionalSpend+=20.9;save();}navigate('ledger');toast(selected?'演示导入完成：新增 1 笔':'没有新增记录，已跳过重复账单');}else if(action==='goal-save'){state.saved=Math.min(8000,state.saved+200);save();closeSheet(false);render();toast('演示目标已存入 ¥200');}else if(action==='transaction'){const t=state.transactions.find(item=>item.id===target.dataset.id);openSheet(escapeHTML(t.name),'演示消费明细',`<div class="card summary-card"><div class="summary-top">消费金额</div><div class="summary-number"><small>¥</small>${money(t.amount,2)}</div><div class="summary-bottom">${icon('clock')}相当于 ${duration(t.amount)}工作收入</div></div><div class="detail-list"><div class="detail-row"><span>支付账户</span><strong>${escapeHTML(t.account)}</strong></div><div class="detail-row"><span>分类</span><strong>${t.category}</strong></div><div class="detail-row"><span>发生时间</span><strong>${escapeHTML(t.date)} ${escapeHTML(t.time)}</strong></div></div>`);}else if(action==='reset')openSheet('重新开始演示？','这会清除在此预览中修改的工作信息、心愿和记录，恢复最初的演示数据。',`<button class="sheet-button" data-action="confirm-reset">恢复演示初始状态</button><button class="sheet-button light" data-action="close-sheet">保留当前修改</button>`);else if(action==='confirm-reset'){state=defaults();save();navigate('home');toast('演示已恢复，可以重新体验');}else if(['budget','notifications','accounts','privacy','about'].includes(action))infoSheet(action);});
document.addEventListener('input',event=>{if(event.target.id==='calc-price')updateCalculator();});
document.addEventListener('submit',event=>{if(event.target.id==='work-form'){event.preventDefault();const data=new FormData(event.target),next={};for(const key of ['salary','days','hours','commute','workCost'])next[key]=Number(data.get(key));if(next.salary<=0||next.days<=0||next.hours<=0)return;Object.assign(state,next);save();closeSheet(false);render();toast('工作信息已更新，换算会同步变化');}else if(event.target.id==='expense-form'){event.preventDefault();const data=new FormData(event.target),amount=Number(data.get('amount')),name=String(data.get('name')).trim();if(!name||!Number.isFinite(amount)||amount<=0)return;state.transactions.unshift({id:'manual-'+Date.now(),name:name.slice(0,40),amount,category:'日常',date:'今天',time:'刚刚',account:'手动记录',icon:'bag'});state.additionalSpend+=amount;save();navigate('ledger');toast('这笔日常已经记下');}});
backdrop.addEventListener('click',()=>closeSheet());
document.addEventListener('keydown',event=>{if(sheet.hidden)return;if(event.key==='Escape')closeSheet();if(event.key==='Tab'){const focusable=[...sheet.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]')];if(!focusable.length){event.preventDefault();return;}const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===sheet)){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
render();
window.__timeworthPreview={navigate,reset:()=>{state=defaults();save();page='home';render();},getState:()=>JSON.parse(JSON.stringify(state))};
